const d=[{id:"mcii",title:"Wang, Wang und Gai · 2021 · Mentales Kontrastieren mit Wenn-dann-Plänen",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"CF06: 21 Artikel, 24 unabhängige Effekte, 15.907 Teilnehmende. Ein gewünschtes Ergebnis mit Hindernissen zu vergleichen und Wenn-dann-Pläne zu ergänzen zeigte im Durchschnitt einen kleinen bis mittleren Vorteil für Ziele (g = 0,336).",limitation:"Mögliche Publikationsverzerrung; Schätzung in der Sensitivitätsanalyse g = 0,242. Ziele und Gruppen waren verschieden. Das ist kein Effekt auf Selbstvertrauen oder des ODA-Kurses."},{id:"self-compassion",title:"Han und Kim · 2023 · Programme für Selbstmitgefühl",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"CF07: In 56 randomisierten Studien zeigten unterschiedliche Programme für Selbstmitgefühl unmittelbar danach im Durchschnitt kleine bis mittlere Effekte auf psychische Belastung.",limitation:"Insgesamt hohes Verzerrungsrisiko; weniger Vergleiche mit aktiven Angeboten oder Onlineprogrammen. Nicht vorab registriert. Ein einzelner unterstützender Satz und dieser Kurs wurden nicht geprüft."},{id:"monitoring",title:"Harkin und Team · 2016 · Fortschritte bei Zielen beobachten",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"CF04: Verstärkte Fortschrittskontrolle verbesserte die Zielerreichung im Durchschnitt in 138 randomisierten Studien mit 19.951 Menschen (d = 0,40).",limitation:"Ziele und Methoden unterschieden sich. Diese konkrete Zusammenfassung und der Rückblick wurden nicht geprüft. Moderatoranalysen verlangen kein öffentliches Teilen."},{id:"CF02",title:"Sitzmann und Yeo · 2013 · Frühere Leistung und Selbstwirksamkeit",url:"https://doi.org/10.1111/peps.12035",type:"research",finding:"In 38 Studien mit wiederholten Messungen und 5.414 Menschen hing frühere Leistung stärker mit späterem Vertrauen in die Aufgabe zusammen als dieses Vertrauen mit späterer Leistung, nachdem zeitliche Trends berücksichtigt wurden.",limitation:"Meist Studien mit Studierenden. Zeitliche Zusammenhänge klären keine Ursache, machen Selbstvertrauen nicht nutzlos und beweisen nicht, dass winzige Handlungen das allgemeine Selbstbild verändern."},{id:"CF04",title:"Harkin und Team · 2016 · Fortschritte bei Zielen beobachten",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Verstärkte Fortschrittskontrolle verbesserte die Zielerreichung im Durchschnitt in 138 randomisierten Studien mit 19.951 Menschen (d = 0,40).",limitation:"Verschiedene Ziele und Methoden. Die konkrete ODA-Notiz und der Rückblick wurden nicht geprüft. Moderatoranalysen machen öffentliches Teilen nicht erforderlich."},{id:"CF05",title:"Gollwitzer und Sheeran · 2006 · Wenn-dann-Pläne",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"Eine Auswertung von 94 unabhängigen Tests mit 8.461 Teilnehmenden fand durchschnittliche Vorteile für Ziele durch Pläne, die eine wichtige Situation mit einer zielgerichteten Handlung verbinden.",limitation:"Verschiedene Methoden und Gruppen, hauptsächlich Studierende; experimentelle und korrelative Studien. Daraus folgt kein Effekt eines Kurses für Selbstvertrauen oder einer bestimmten Methode des Rückwärtszählens."},{id:"CF07",title:"Han und Kim · 2023 · Programme für Selbstmitgefühl",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"In 56 randomisierten Studien zeigten unterschiedliche Programme für Selbstmitgefühl unmittelbar danach im Durchschnitt kleine bis mittlere Effekte auf Maße psychischer Belastung.",limitation:"Insgesamt hohes Verzerrungsrisiko, weniger Vergleiche mit aktiven Angeboten oder Onlineprogrammen und keine Vorabregistrierung. Diese kurze ODA-Übung entspricht nicht den geprüften Programmen."},{id:"CF08",title:"Breines und Chen · 2012 · Selbstmitgefühl und Motivation zur Verbesserung",url:"https://self-compassion.org/wp-content/uploads/publications/selfimp.motivation.pdf",type:"research",finding:"In einem randomisierten Experiment nach Fehlverhalten erhöhte mitfühlendes Schreiben die berichtete Motivation von Studierenden, etwas wiedergutzumachen und das Verhalten nicht zu wiederholen. 91 Studierende wurden ausgewertet.",limitation:"Berichtete Motivation war keine erledigte Wiedergutmachung oder dauerhafte Kompetenz. Eine unabhängige direkte Wiederholung dieses genauen Vorgehens wurde im Dossier nicht verifiziert."},{id:"CF11",title:"Craske und Team · 2014 · Übersicht zur lernorientierten Exposition",url:"https://doi.org/10.1016/j.brat.2014.04.006",type:"research",finding:"Die klinische Übersicht betont, eine konkrete Befürchtung mit dem tatsächlichen Geschehen zu vergleichen. Unmittelbar sinkende Angst ist für das Lernen nicht erforderlich.",limitation:"Beschreibende Übersicht, keine zusammengefasste Studie. Sie bestätigt weder ODAs kurze Übung noch die allgemeine Überlegenheit einer Technik. Sie rechtfertigt keine unbegleitete Traumaexposition oder das Aufgeben tatsächlicher Schutzmaßnahmen."},{id:"CF12",title:"NHS · Ängsten begegnen",url:"https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/facing-your-fears/",type:"guidance",finding:"Die öffentliche Anleitung beschreibt, angstauslösende Situationen aufzulisten, einzuschätzen, zu ordnen und überschaubare Situationen ohne Eile zu üben.",limitation:"Empfehlung, keine Studie. Ihre Regel einer halbierten Angst für den nächsten Schritt unterscheidet sich von lernorientierten Modellen. Die früheren numerischen ODA-Grenzen waren nicht bestätigt."},{id:"CF13",title:"NIMH · Soziale Angststörung: Was du wissen solltest",url:"https://www.nimh.nih.gov/health/publications/social-anxiety-disorder-more-than-just-shyness",type:"guidance",finding:"Professionelle Hilfe ist angemessen, wenn soziale Angst den Alltag beeinträchtigt. Eine Fachperson beurteilt Symptome und mögliche Ursachen.",limitation:"Öffentliche klinische Empfehlung, kein Experiment. Eine Lektion stellt keine Diagnose. Warte nicht auf eine bestimmte Dauer, bevor du Hilfe suchst. ODA ersetzt keine Behandlung."}],n=[{schemaVersion:2,revision:4,id:"confidence-1",courseId:"confidence",locale:"de",title:"Beschreib die Angst. Urteile nicht über dich.",goal:"Beschreib eine schwierige Situation fair. Sag dann einen hilfreichen Satz, wenn es für dich sicher ist.",minutes:{learning:6,rehearsal:1,suggestedAction:2,review:2},direction:{hook:"Was hast du diese Woche lieber nicht gesagt? Such eine sichere Gelegenheit für einen hilfreichen Satz.",reason:{id:"reason-to-speak",label:"Was zählt hier? Oder was kostet dich das Schweigen?",kind:"text",maxLength:160,optional:!0,suggestions:["Meine Ideen einbringen","Hilfreiche Gedanken aussprechen","Sagen, was ich brauche"]},why:{id:"why-speaking",label:"Warum gehört es zu deinem gewünschten Leben, dich einzubringen?",kind:"text",maxLength:300,optional:!0},tradeOff:{id:"cost-of-silence",label:"Falls du geschwiegen hast: Was hat es dich gekostet?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["„Ich kann mich einfach nicht einbringen“ ist ein Urteil über dich als Person. „Wenn ich eine Idee vorstelle, werde ich nervös“ beschreibt eine Situation. Dort kannst du den nächsten Schritt üben. Ein Urteil lässt sich nicht üben.","Warte nicht, bis du selbstsicher klingst. Beschreib, was gerade passiert, und wähle einen hilfreichen Satz. Einen Gedanken umzuformulieren ist Vorbereitung. Deinen Satz zu sagen ist der nächste echte Schritt. Die Antwort kann dich enttäuschen. Halte sie trotzdem fest.","Wähle eine sichere Gelegenheit. Könnte das Sprechen dich gefährden, schütze dich oder bitte um Unterstützung. Du entscheidest dich für einen Schritt. Dein Wert steht hier nicht auf dem Prüfstand."],example:{title:"Annas Vorschlag",text:"Anna hat diese Woche zweimal geschwiegen. Sie möchte ihre Ideen einbringen und bereitet für eine sichere Teambesprechung eine Frage vor: „Können wir die kürzere Checkliste eine Schicht lang testen?“ Sie fragt trotz ihrer Nervosität. Ihre Vorgesetzte will am Montag darüber sprechen. Anna hält ihre Frage und die Antwort fest. Über die Idee ist noch nicht entschieden."}},move:{invitation:"Wähle einen hilfreichen Satz. Mach ihn kurz genug für die nächste sichere Gelegenheit.",instructions:["Trag deinen tatsächlichen Satz unter „Handlung“ ein. Wähle das passende Startsignal und den Ort.","Sag ihn sicher. Üben ist Vorbereitung. Private Details kannst du außerhalb von ODA lassen."],prompts:[{id:"actual-sentence-and-opening",label:"Was sagst du? Bei welcher konkreten Gelegenheit?",help:"Ändere den Satz unter „Handlung“ oder wähle „Meinen Plan außerhalb von ODA behalten“.",kind:"text",maxLength:160,optional:!0,visible:!0}],suggestions:{action:["Fragen: Können wir die kürzere Checkliste testen?","Sagen: Ich würde diesen Schritt zuerst prüfen.","Fragen: Können wir die Abgabefrist klären?"],minimum:["Nach der kürzeren Checkliste fragen","Meinen gewählten Satz sagen","Meinen gewählten Satz senden"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],cue:["Bei der heutigen Teambesprechung um 15 Uhr","Beim Mittagessen mit meinem vertrauten Kollegen"],place:["In unserem Besprechungsraum","In unserem vertrauten Teamchat"],minutes:[2,1,5],fallback:["Meinen Satz vom Zettel ablesen","Nach der Besprechung im Teamchat schreiben","Eine vertraute Person um Unterstützung bitten"],observation:["Ob ich meinen Satz gesagt habe","Die Antwort, auch wenn keine kam","Was geholfen oder mich aufgehalten hat"]},suggested:{action:"Fragen: Können wir die kürzere Checkliste testen?",minimum:"Nach der kürzeren Checkliste fragen",minutes:2,cueHint:"Bei der heutigen Teambesprechung um 15 Uhr",placeHint:"In unserem Besprechungsraum",obstacleHint:"Ich zögere, obwohl ich gerade sprechen könnte.",fallbackHint:"Meinen Satz vom Zettel ablesen",observationHint:"Ob ich den Satz gesagt habe und welche Antwort kam"},stopRule:"Könnte das Sprechen dich gefährden, pausiere. Wähle Schutz oder Unterstützung.",accessibleAlternative:"Nutze deine gewohnte Kommunikationsform, eine sichere schriftliche Nachricht oder eine Bitte um Unterstützung."},result:{question:"Hast du deinen Satz gesagt?",observationPrompt:"Was hast du getan? Welche Antwort hast du tatsächlich bekommen?"},judgment:{primary:{id:"prepared-safe-opening",scenario:"Anna hat zwei Punkte für eine sichere Teambesprechung vorbereitet. Die Vorgesetzte bittet um Vorschläge. Anna wird nervös und denkt: „Ich kann das nicht.“",question:"Welcher nächste Schritt passt am besten zu dieser Lektion?",options:[{id:"extra-review",text:"Eine Kollegin bitten, beide Punkte zu prüfen, bevor sie entscheidet, ob sie sich in der Besprechung einbringt.",feedback:"Eine Prüfung kann helfen, wenn Informationen fehlen. Anna hat ihre Punkte vorbereitet und kann sicher sprechen. Eine weitere Prüfung verschiebt den Versuch. Beschreib die Situation und sag jetzt einen Satz."},{id:"use-one-sentence",text:"Den konkreten Moment beschreiben und einen vorbereiteten Satz sagen, solange sie sich einbringen kann.",feedback:"Das passt zu diesem Moment. Anna hat einen Satz vorbereitet und kann ihn sicher sagen. Sie kann ihre Nervosität fair beschreiben und sich trotzdem einbringen. Entscheidend ist, was sie tut, nicht ob sie Selbstvertrauen spürt."},{id:"wait-for-ease",text:"Beide Punkte nochmals üben und warten, bis die Nervosität nachlässt, bevor sie eine Gelegenheit auswählt.",feedback:"Üben hilft beim Vorbereiten. Anna ist bereits vorbereitet. Wartet sie auf weniger Nervosität, könnte die Gelegenheit verstreichen. Sie kann ihren Satz auch nervös sagen und anschließend festhalten, was passiert."}],bestOptionId:"use-one-sentence"}},carry:{takeaway:"Eine faire Beschreibung zeigt dir den nächsten Schritt. Ein Etikett macht zu früh Schluss.",identityExample:"Wenn du deinen Satz gesagt hast: „Ich habe trotz Nervosität gesprochen.“",followUp:{questionId:"opening-result",question:"Was ist passiert, als die Gelegenheit kam?",observationPrompt:"Was hast du tatsächlich bemerkt?",adjustmentPrompt:"Wie passt der nächste Versuch besser in dein Leben?"}},goDeeper:{sections:[{heading:"Eine Beschreibung, mit der du etwas anfangen kannst",paragraphs:["„Ich kann das nicht“ ist als Urteil zu weit gefasst, um dir den nächsten Schritt zu zeigen. Eine Beschreibung nennt die Situation, das Gefühl und eine mögliche Handlung. Damit ist das Urteil weder widerlegt noch Erfolg versprochen. Auch fehlende Fähigkeiten verschwinden nicht. Du bekommst eine kleinere Frage, die du beim Ausprobieren beantworten kannst.","Vielleicht brauchst du mehr als einen Satz. Kennst du den Stoff nicht, zählt Vorbereitung. Ist die Situation unsicher, zählt Schutz. Überfordert sie dich immer wieder, zählt Unterstützung. Im Quiz ist die Person vorbereitet und kann sicher sprechen. Es behauptet nicht, dass sofortiges Sprechen immer die beste Entscheidung ist.","Der faire Satz in dieser Lektion ist eine ODA-Lernübung. Forschung zu längeren Programmen für Selbstmitgefühl zeigt nicht, dass diese einzelne Übung Angst behandelt oder Selbstvertrauen verändert. Nutze sie, um einen konkreten nächsten Schritt zu wählen. Beurteile diesen Schritt anhand dessen, was du beobachtest. [CF07]"]},{heading:"Was die Forschung stützt",paragraphs:["Han und Kim fassten 2023 insgesamt 56 randomisierte Studien zu Selbstmitgefühl zusammen. Unmittelbar nach den Programmen fanden sie bei Maßen psychischer Belastung im Durchschnitt kleine bis mittlere Effekte. Das Verzerrungsrisiko war insgesamt hoch. Für Vergleiche mit anderen aktiven Angeboten und für Onlineangebote gab es weniger Belege. Eine Wirkung der einzelnen ODA-Satzübung ist damit nicht nachgewiesen. [CF07]","Harkin und sein Team fassten 2016 insgesamt 138 randomisierte Studien zur Fortschrittskontrolle zusammen. Maßnahmen zur Kontrolle verbesserten im Durchschnitt die Zielerreichung. Ziele und Formen des Festhaltens unterschieden sich. Die konkrete ODA-Zusammenfassung und der Rückblick am nächsten Tag wurden dort nicht untersucht. Hier hilft die Notiz, einen Plan mit dem tatsächlichen Versuch zu vergleichen. Öffentlich teilen musst du sie nicht. [CF04]","Du kannst festhalten, dass dein Gefühl gleich geblieben ist, eine Frage unbeantwortet blieb oder du pausiert hast. Das sind unterschiedliche Beobachtungen. Keine rechtfertigt ein Urteil über deine ganze Person. Richte die nächste Entscheidung nach den Fakten, deinen Umständen und dem Leben aus, das du führen möchtest."]}],sourceIds:["CF07","CF04"]}},{schemaVersion:2,revision:2,id:"confidence-2",courseId:"confidence",locale:"de",title:"Noch am Üben? Lass jemanden deine Idee hören",goal:"Sag eine kleinere Version deines gewählten Satzes bei einer sicheren Gelegenheit im Alltag.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Du übst deinen fertigen Satz immer noch? Such eine überschaubare Gelegenheit, ihn wirklich zu sagen.",reason:{id:"polishing-cost-at-safe-opening",label:"Falls du weiter gefeilt hast: Was hat dich die verpasste sichere Gelegenheit gekostet?",kind:"text",maxLength:160,optional:!0,suggestions:["Meine Idee jemandem sagen","Benötigte Informationen erfragen","Vom Vorbereiten zum Ausprobieren kommen"]},why:{id:"why-smaller-opening",label:"Warum hilft dir diese Gelegenheit bei dem, was du erreichen möchtest?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Behalte den Satz und dein Anliegen aus der ersten Lektion. War die Gelegenheit zu anspruchsvoll, ändere die Zuhörenden oder den Ort. Auch in einem kleineren Gespräch nutzt du die Fähigkeit. Einen fertigen Satz allein umzuschreiben bleibt Vorbereitung, selbst wenn es leichter fällt.","Schrittweises Üben beginnt mit überschaubaren Situationen. Du kannst aus einer Antwort lernen, obwohl du noch Angst hast. Wähle eine sichere Person oder einen sicheren Nachrichtenkanal. Du darfst denselben Schritt wiederholen. Fehlen Informationen, besorg sie zuerst und lege einen Termin fürs Gespräch fest. Überwältigende Angst braucht Unterstützung, keine größere Herausforderung."],example:{title:"Ben stellt seine vorbereitete Frage",text:"Beim Mittagessen am Dienstag liest Ben die Frage aus Lektion eins nochmals. Statt sie wieder umzuschreiben, schickt er sie einem vertrauten Kollegen: „Können wir die kürzere Checkliste testen?“ Der Kollege fragt, welche Schicht er meint. Ben antwortet. Die Idee ist noch offen. Aber er hat seinen Satz genutzt und jemand hat ihn gehört."}},move:{invitation:"Behalte deinen Satz. Wähle die nächste überschaubare, sichere Gelegenheit dafür.",instructions:["Behalte deinen gespeicherten Satz und das Minimum. Ändere bei Bedarf nur Person oder Kommunikationsweg.","Lege Gespräch und Ort vor dem Speichern fest. Halte fest, was du sagst und hörst."],prompts:[{id:"actual-smaller-opening",label:"Wer kann deinen gespeicherten Satz hören? Bei welchem konkreten Gespräch?",kind:"text",maxLength:160,optional:!0,visible:!0}],suggestions:{action:["Fragen: Können wir die kürzere Checkliste testen?","Meinem Kollegen meine gewählte Idee schicken","Meine gespeicherte Bitte unter vier Augen äußern"],minimum:["Einen vorbereiteten Satz sagen","Einen hilfreichen Satz senden"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],cue:["Beim Mittagessen mit meinem vertrauten Kollegen","Bei der heutigen Teambesprechung um 15 Uhr"],place:["An unserem üblichen Mittagstisch","Im Chat mit meinem vertrauten Kollegen"],minutes:[2,1,5],fallback:["Den Satz nach unserem Mittagsgespräch senden","Meine Notiz nutzen, ohne den Satz umzuschreiben"],observation:["Ob ich meinen Satz gesagt habe","Die Antwort, auch wenn keine kam"]},suggested:{action:"Fragen: Können wir die kürzere Checkliste testen?",minimum:"Einen vorbereiteten Satz sagen",minutes:2,cueHint:"Beim Mittagessen mit meinem vertrauten Kollegen",placeHint:"An unserem üblichen Mittagstisch",obstacleHint:"Unser Mittagsgespräch fällt aus.",fallbackHint:"Den Satz nach unserem Mittagsgespräch senden",observationHint:"Ob ich meinen Satz gesagt habe"},stopRule:"Pausiere bei Gefahr oder überwältigender Belastung. Hole Unterstützung, wenn Angst deinen Alltag beeinträchtigt.",accessibleAlternative:"Tippe, nutze Gebärden oder deine gewohnte Kommunikationshilfe. Nach der Vorbereitung braucht das echte Gespräch einen Termin."},result:{question:"Hast du deinen Satz bei der gewählten Gelegenheit gesagt?",observationPrompt:"Was hast du gesagt oder gesendet? Welche Antwort kam danach?"},judgment:{primary:{id:"ready-question-smaller-opening",scenario:"Ben hat seine Frage dreimal umgeschrieben. Ein vertrauter Kollege bietet ein Gespräch unter vier Augen an. Die Präsentation vor dem Team überfordert Ben weiterhin.",question:"Welcher Versuch passt zu der verfügbaren Gelegenheit?",options:[{id:"private-ready-question",text:"Im Gespräch unter vier Augen seine fertige Frage stellen und anschließend die tatsächliche Antwort festhalten.",feedback:"So nutzt Ben dieselbe Fähigkeit in einer überschaubaren Situation, in der jemand zuhört. Er kann aus der Antwort lernen. Dafür muss er weder ruhig sein noch sich zu einer Präsentation verpflichten."},{id:"polish-first",text:"Im Gespräch um eine weitere Prüfung seines Textes bitten und danach entscheiden, wann er die Frage stellt.",feedback:"Eine weitere Prüfung hilft, wenn Informationen fehlen. Hier ist die Frage fertig. Weiteres Feilen verschiebt das Sprechen. Nutze die kleinere Gelegenheit, die bereits da ist."},{id:"book-presentation",text:"Für nächste Woche eine Präsentation vor dem gesamten Team buchen, damit der Versuch ein anspruchsvolleres Ziel hat.",feedback:"Ein größeres Publikum kann später sinnvoll sein. Jetzt bleibt damit die überschaubare Gelegenheit ungenutzt. Ben kann zuerst unter vier Augen fragen und danach entscheiden, ob er wiederholt oder die Situation verändert."}],bestOptionId:"private-ready-question"}},carry:{takeaway:"Eine kleinere Gelegenheit soll dir das Sprechen ermöglichen, statt dich endlos vorbereiten zu lassen.",identityExample:"Wenn du deinen Satz gesagt hast: „Jemand hat meine Idee gehört.“",followUp:{questionId:"smaller-opening-result",question:"Konntest du deinen Satz bei der kleineren Gelegenheit nutzen, oder blieb es bei Vorbereitung?",observationPrompt:"Welche Handlung und welche Antwort hast du festgehalten?",adjustmentPrompt:"Wiederholen, eine andere Gelegenheit wählen oder Unterstützung holen?"}},goDeeper:{sourceIds:["CF12","CF11","CF13"],sections:[{heading:"Schrittweises Üben folgt unterschiedlichen Ansätzen",paragraphs:["Der NHS empfiehlt, Situationen aufzuschreiben, vor denen du Angst hast, ihre Schwierigkeit einzuschätzen und mit leichteren zu beginnen. Für den nächsten Schritt nutzt die Anleitung die Regel, dass die Angst auf die Hälfte sinkt. Das ist eine Empfehlung, keine überall experimentell bestätigte Grenze. Die früheren ODA-Regeln von drei oder vier auf zehn oder zwei niedrigen Bewertungen waren dadurch nicht belegt. Freiwillige Bewertungen können dein Erleben beschreiben. Sie entscheiden nicht darüber, ob ein Versuch zählt. [CF12]","Die klinische Übersicht von Craske und ihrem Team betont den Vergleich einer konkreten Befürchtung mit dem Ergebnis. Dass die Angst sofort nachlässt, ist dort keine notwendige Bedingung zum Beenden. Die Ansätze unterscheiden sich. ODA übernimmt überschaubare Schritte für selbst gewählte Alltagssituationen, ohne eine Expositionstherapie nachzubilden. Ein fertiger Satz an eine sichere Person ist ein wirklicher Sprechversuch. Ihn allein zu üben bleibt Vorbereitung. Beides garantiert keinen Zuwachs an Selbstvertrauen. [CF11, CF12]"]},{heading:"Wahlfreiheit und Schutz gehören zum Versuch",paragraphs:["Ein kleinerer Schritt ist nicht automatisch sicherer. Auch eine private Nachricht kann im Beruf, in der Familie oder im jeweiligen kulturellen Umfeld Risiken bergen. Wähle eine Situation, in der die Handlung für dich sicher ist. Behalte Schutzmaßnahmen und Grenzen bei. Die klinische Übersicht erlaubt weder, Schutz aufzugeben, Misshandlung auszuhalten, noch allein traumatische Auslöser zu bearbeiten. Du darfst aufhören oder Unterstützung wählen, ohne erst sinkende Angst nachweisen zu müssen. [CF11]","Das NIMH empfiehlt professionelle Hilfe, wenn soziale Angst den Alltag beeinträchtigt. Eine Fachperson beurteilt die Situation. Dieser Kurs kann ihre Ursache nicht diagnostizieren. Hilfe kann schon vor Abschluss einer Lektion oder vor wiederholten Versuchen passen. Fehlen Informationen, besorg sie und lege eine spätere Gelegenheit fest. Bei Gefahr oder überwältigender Belastung kann eine andere Situation oder Unterstützung der sinnvolle nächste Schritt sein. Halte fest, was du tatsächlich gewählt und getan hast. [CF13]"]}]}},{schemaVersion:2,revision:2,id:"confidence-3",courseId:"confidence",locale:"de",title:"Eine unangenehme Antwort ist nicht die ganze Geschichte",goal:"Halte Satz und Antwort fest. Vergleiche eine Erwartung nur, wenn du sie vorher gespeichert hast.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Die Antwort hat wehgetan? Was zeigt sie dir konkret für den nächsten Versuch?",reason:{id:"reason-for-factual-record",label:"Was zählt hier mehr, als fehlerlos zu wirken?",kind:"text",maxLength:160,optional:!0,suggestions:["Aus wirklichen Rückmeldungen lernen","Weiter hilfreiche Fragen stellen","Mich bei Bedarf schützen"]},why:{id:"why-record-speaking",label:"Welche Entscheidung erleichtert dir eine sachliche Notiz?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Bleib bei deinem gewählten Sprechversuch. Willst du später vergleichen, speichere vor der nächsten Gelegenheit eine konkrete Erwartung. Eine nachträglich rekonstruierte Erwartung ist eine Erinnerung, keine festgehaltene Vorhersage. Sag deinen Satz. Notiere anschließend deine Handlung und die tatsächliche Antwort.","Fortschritte zu beobachten hat in vielen Studien die Zielverfolgung unterstützt. Diese kurze Notiz ist aber eine ungeprüfte Anpassung. Gefühle gehören neben die Fakten: „Ich habe gefragt. Sie sagten, das sei schon besprochen. Mir war es peinlich.“ Die Worte beweisen keine Absicht. Behalte echte Kritik oder schlechte Behandlung im Blick. Entscheide danach, ob du etwas änderst, Unterstützung brauchst oder eine Grenze setzt."],example:{title:"Lukas hält auch die schwierige Antwort fest",text:"Vor der Besprechung am Donnerstag speichert Lukas: „Meine Frage wird abgewiesen.“ Er fragt nach dem Zeitplan. Eine Kollegin sagt: „Das haben wir gestern besprochen.“ In einer ruhigen Ecke notiert Lukas ihre Worte und seine Verlegenheit. Vor der nächsten Frage liest er die gestrigen Notizen. Er findet das Gespräch weiterhin unangenehm. Handlung und Kritik stehen beide in seiner Notiz."}},move:{invitation:"Bleib bei deinem Sprechversuch. Halte auch die Antwort fest.",instructions:["Behalte deinen Satz. Speichere auf Wunsch vor dieser Gelegenheit eine konkrete Erwartung.","Notiere nach dem Versuch deine Handlung, die Antwort und alles, was unklar bleibt."],prompts:[{id:"prediction-before-opening",label:"Welche konkrete Antwort erwartest du, bevor du es versuchst?",help:"Lass die Erwartung aus, wenn du nur Handlung und Antwort festhalten möchtest.",kind:"text",maxLength:300,optional:!0,planField:"prediction"}],suggestions:{action:["Fragen: Können wir die Abgabefrist klären?","Meine gespeicherte Idee teilen und die Antwort notieren"],minimum:["Einen vorbereiteten Satz sagen","Eine hilfreiche Frage senden"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],cue:["Bei der heutigen Teambesprechung um 15 Uhr","Nach dem Mittagessen im Chat mit meinen Kollegen"],place:["In unserem Besprechungsraum","Im Chat mit meinen vertrauten Kollegen"],minutes:[2,1,5],fallback:["Den Satz nach unserem Mittagsgespräch senden","Meine Notiz nutzen, ohne den Satz umzuschreiben"],observation:["Meine Handlung und die tatsächliche Antwort","Was an der Antwort unklar bleibt"]},suggested:{action:"Fragen: Können wir die Abgabefrist klären?",minimum:"Einen vorbereiteten Satz sagen",minutes:2,cueHint:"Bei der heutigen Teambesprechung um 15 Uhr",placeHint:"In unserem Besprechungsraum",obstacleHint:"Unsere Besprechung endet, bevor Fragen dran sind.",fallbackHint:"Den Satz nach unserem Mittagsgespräch senden",observationHint:"Meine Handlung und die tatsächliche Antwort"},stopRule:"Hör bei Gefahr oder überwältigender Belastung auf. Eine sachliche Notiz verlangt niemals, schlechte Behandlung auszuhalten.",accessibleAlternative:"Nutze eine sichere Nachricht oder Kommunikationshilfe. Du kannst die Notiz für dich behalten."},result:{question:"Hast du deinen Satz gesagt?",observationPrompt:"Was ist passiert? Was hast du gefühlt? Was bleibt unklar?"},judgment:{primary:{id:"critical-reply-complete-record",scenario:"Lukas stellt seine Frage. Eine Kollegin sagt: „Das haben wir gestern besprochen.“ Seine Stimme zittert und ihm ist die Situation peinlich.",question:"Welche Notiz hilft am besten beim nächsten Versuch?",options:[{id:"postpone-feedback-review",text:"Heute Frage und Nervosität festhalten. Morgen die Formulierung prüfen und dann entscheiden, ob die Rückmeldung einen Schritt erfordert.",feedback:"Handlung und Nervosität festzuhalten hilft. Die Antwort aufzuschieben nimmt dem morgigen Rückblick aber Kontext. Notiere die Worte der Kollegin gleich neben der Frage. Schau dir vor einer Änderung beides an."},{id:"private-only-route",text:"Die Antwort festhalten und künftig alle Fragen privat schicken, um keine weitere Besprechung zu unterbrechen.",feedback:"Ein privater Weg kann passen, besonders bei wiederholt schädlichem Verhalten. Diese eine Antwort belegt keine Absicht. Halte die Worte fest, bevor du die passende Grenze oder Änderung wählst."},{id:"keep-facts-feeling",text:"Frage, genauen Wortlaut der Antwort und Verlegenheit festhalten. Vor der nächsten Frage die früheren Notizen prüfen.",feedback:"So bleiben Handlung und unbequeme Rückmeldung erhalten, ohne eine Absicht zu erfinden. Die Notizen zu prüfen klärt eine mögliche Informationslücke. Bei schädlicher Behandlung kann Lukas weiterhin Unterstützung suchen."}],bestOptionId:"keep-facts-feeling"}},carry:{takeaway:"Halte Handlung, Antwort und Gefühle fest. Was du nicht weißt, darf offenbleiben.",identityExample:"Wenn du die Antwort notiert hast: „Ich habe auch die schwierige Rückmeldung berücksichtigt.“",followUp:{questionId:"prediction-and-reply-result",question:"Was ändert die tatsächliche Antwort an deinem nächsten Sprechversuch?",observationPrompt:"Vergleiche die vorher gespeicherte Erwartung, falls vorhanden, mit der Antwort.",adjustmentPrompt:"Welche Information, Unterstützung oder Grenze passt als Nächstes?"}},goDeeper:{sourceIds:["CF04","CF11","CF02"],sections:[{heading:"Fortschritte beobachten hilft Zielen, mit Grenzen beim Übertragen",paragraphs:["Harkin und sein Team fassten 138 randomisierte Studien mit 19.951 Menschen zusammen. Maßnahmen, die die Fortschrittskontrolle verstärkten, verbesserten die Zielerreichung im Durchschnitt. Der standardisierte Effekt betrug 0,40. Ziele und Methoden waren verschieden. In Moderatoranalysen gingen schriftliches Festhalten und Berichten mit größeren Effekten einher. Diese Vergleiche machen öffentliches Teilen nicht nötig. Sie zeigen auch nicht, dass diese konkrete zweiminütige Notiz Selbstvertrauen verändert. Deine Notizen dürfen privat bleiben. [CF04]","Hier zählen drei unterschiedliche Dinge: Plan, Handlung und äußeres Ergebnis. Ein gespeicherter Satz ist ein Plan. Ihn zu sagen oder zu senden ist eine Handlung. Zustimmung, Ablehnung, Kritik oder keine Antwort sind ein eigenes Ergebnis. Halte nur fest, was du weißt. Hast du vorher keine Erwartung gespeichert, erfinde keine für den Vergleich. Beim nächsten Versuch kannst du eine neue Erwartung notieren. Die konkrete ODA-Notiz und ihr Zeitplan bleiben eine Anpassung. [CF04, CF11]"]},{heading:"Beobachtungen können Zweifel und schwache Pläne hinterfragen",paragraphs:["Die lernorientierte Übersicht zur Exposition betont eine konkrete Vorhersage und das tatsächliche Geschehen. Sie belegt weder, dass jede Form des Nachdenkens Grübeln verhindert, noch verlangt sie, am Ende ruhig zu sein. ODA überträgt den Vergleich auf einen sicheren Sprechversuch im Alltag. Die Notiz kann zeigen, dass du dich trotz Nervosität eingebracht hast. Sie kann auch zeigen, dass Informationen, eine andere Situation oder eine schützende Grenze nötig waren. Enttäuschende Informationen gehören ebenfalls hinein. [CF11]","Eine Auswertung von 38 Studien mit wiederholten Messungen und 5.414 Menschen fand nach Kontrolle zeitlicher Trends: Frühere Leistung hing stärker mit späterem Vertrauen in die konkrete Aufgabe zusammen als dieses Vertrauen mit späterer Leistung. Meist wurden Studierende untersucht. Zeitliche Zusammenhänge klären keine Ursache und beweisen nicht, dass eine winzige Handlung das allgemeine Selbstvertrauen verändert. Nutze deine Notizen für den nächsten Versuch. Lass Raum für fehlende Fähigkeiten und äußere Grenzen. [CF02]"]}]}},{schemaVersion:2,revision:2,id:"confidence-4",courseId:"confidence",locale:"de",title:"Dich fertigzumachen behebt den Fehler nicht",goal:"Nutze deine Notiz für eine nötige Korrektur. Oder wähle Unterstützung, wenn du nichts wiedergutzumachen hast.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Der peinliche Moment ist vorbei. Was ist wirklich deine Aufgabe, wieder in Ordnung zu bringen?",reason:{id:"repair-versus-reassurance",label:"Was liegt bei dir? Behebst du es oder suchst du Beruhigung?",kind:"text",maxLength:160,optional:!0,suggestions:["Meine falsche Angabe korrigieren","Mein versäumtes Versprechen wiedergutmachen","Nichts wiedergutzumachen; Unterstützung wählen"]},why:{id:"why-speaking-repair",label:"Was würde eine hilfreiche Korrektur hier verändern?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Schau auf deine Notiz zum Sprechversuch. Hast du falsche Informationen gegeben, eine Zusage versäumt oder einfach eine unangenehme Antwort bekommen? Das verlangt unterschiedliche Schritte. Entschuldige dich nicht für das schädliche Verhalten anderer. Kläre erst, welcher Teil bei dir liegt, bevor du etwas wiedergutmachst.","In einem Experiment erhöhte mitfühlendes Schreiben die Motivation von Studierenden, etwas wiedergutzumachen. Motivation war noch keine erledigte Wiedergutmachung. Sprich fair mit dir und handle: Korrigiere eine Angabe, schlage einen Ersatztermin vor oder bitte um Unterstützung. Diese kurze Anpassung ist keine Behandlung. Die Verlegenheit kann bleiben. Halte fest, was du tatsächlich geändert hast."],example:{title:"Fatima korrigiert das Datum",text:"Fatima hat am Dienstag im Teamchat das falsche Datum für einen Ausflug genannt. Für sich sagt sie: „Das Datum war falsch. Ich kann es korrigieren.“ Sie schickt der gleichen Gruppe das richtige Datum. Vor der nächsten Nachricht will sie den Kalender prüfen. Ihr ist es weiterhin peinlich. Ihre Notiz nennt die Korrektur, kein Urteil über ihre Fähigkeiten."}},move:{invitation:"Nutze deine Notiz. Korrigiere deinen Teil oder wähle passende Unterstützung.",instructions:["Kläre deine Verantwortung. Wähle unten eine passende Korrektur oder Unterstützung.","Nenne die konkrete Angabe oder Bitte um Unterstützung. Nutze einen sicheren Kommunikationsweg."],prompts:[{id:"repair-or-support-choice",label:"Was passt: etwas wiedergutmachen oder Unterstützung ohne Schuldübernahme?",kind:"choice",options:[{id:"repair-owed",label:"Etwas wiedergutmachen"},{id:"support-without-blame",label:"Nichts wiedergutzumachen; Unterstützung wählen"}],optional:!0,visible:!0}],suggestions:{action:["Geprüftes Ausflugsdatum im Teamchat senden","Nächsten Dienstagmittag als Ersatztermin anbieten","Eine vertraute Person um konkrete Unterstützung bitten"],minimum:["Das richtige Ausflugsdatum senden","Den Ersatztermin vorschlagen","Die Bitte um Unterstützung senden"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1}],cue:["Nach der Prüfung des Ausflugsdatums in der Mittagspause","Nach dem Mittagessen, wenn mein vertrauter Freund kann"],place:["Im ursprünglichen sicheren Chat","In einem privaten Gespräch mit einer vertrauten Person"],minutes:[2,1,5],fallback:["Anderen sicheren Weg nutzen; unsicheren Kontakt pausieren","Eine vertraute Person um Unterstützung bitten"],observation:["Das korrigierte Datum und eine mögliche Antwort","Mein Vorschlag zur Wiedergutmachung und die Antwort","Meine Bitte um Unterstützung und eine mögliche Antwort"],bundles:[{action:"Geprüftes Ausflugsdatum im Teamchat senden",minimum:"Das richtige Ausflugsdatum senden",cue:"Nach der Prüfung des Ausflugsdatums in der Mittagspause",place:"Im ursprünglichen sicheren Chat",fallback:"Anderen sicheren Weg nutzen; unsicheren Kontakt pausieren",observation:"Das korrigierte Datum und eine mögliche Antwort",minutes:2,kind:"practice"},{action:"Nächsten Dienstagmittag als Ersatztermin anbieten",minimum:"Den Ersatztermin vorschlagen",cue:"Nach der Kalenderprüfung in der Mittagspause",place:"Im ursprünglichen sicheren Chat",fallback:"Anderen sicheren Weg nutzen; unsicheren Kontakt pausieren",observation:"Mein Vorschlag zur Wiedergutmachung und eine mögliche Antwort",minutes:2,kind:"practice"},{action:"Eine vertraute Person um konkrete Unterstützung bitten",minimum:"Die Bitte um Unterstützung senden",cue:"Nach dem Mittagessen, wenn mein vertrauter Freund kann",place:"In unserem privaten Chat",fallback:"Andere vertraute Person fragen; unsicheren Kontakt pausieren",observation:"Meine Bitte um Unterstützung und eine mögliche Antwort",minutes:2,kind:"support"}]},suggested:{requiresChoice:!0,action:"Geprüftes Ausflugsdatum im Teamchat senden",minimum:"Das richtige Ausflugsdatum senden",minutes:2,cueHint:"Nach der Prüfung des Ausflugsdatums in der Mittagspause",placeHint:"Im ursprünglichen sicheren Chat",obstacleHint:"Dieser sichere Kommunikationsweg ist gerade nicht verfügbar.",fallbackHint:"Anderen sicheren Weg nutzen; unsicheren Kontakt pausieren",observationHint:"Das korrigierte Datum und eine mögliche Antwort"},stopRule:"Fehlt ein sicherer Weg, nutze einen anderen. Ist Kontakt unsicher, pausiere und suche Schutz oder Unterstützung.",accessibleAlternative:"Tippe, nutze Gebärden oder Hilfe. Du kannst auch Unterstützung erbitten. Eine Antwort ist nicht erforderlich."},result:{question:"Hast du deine gewählte Korrektur oder Bitte um Unterstützung umgesetzt?",observationPrompt:"Was hast du korrigiert, angeboten oder erbeten? Welche Antwort kam?"},judgment:{primary:{id:"wrong-date-useful-repair",scenario:"Fatima hat im sicheren Teamchat das falsche Datum genannt. Ein Kollege weist sie darauf hin. Sie hat das richtige Datum inzwischen geprüft.",question:"Welche Antwort behebt das tatsächliche Problem?",options:[{id:"correct-and-check",text:"Der Gruppe das richtige Datum schicken und vor der nächsten Nachricht das Datum nochmals prüfen.",feedback:"Damit erhalten alle die nötige Information. Die Prüfung kann einer Wiederholung vorbeugen. Fatima kann fair mit sich sprechen und den Fehler beheben. Sie muss sich dafür nicht weniger schämen."},{id:"explain-shame-first",text:"Dem Kollegen schreiben, wie peinlich es ihr ist, und fragen, ob die anderen ihr noch vertrauen.",feedback:"Unterstützung zu suchen kann sinnvoll sein. Beruhigung korrigiert aber die Information der Gruppe nicht. Schicke zuerst das geprüfte Datum im sicheren Chat. Wähle danach auf Wunsch Unterstützung."},{id:"rewrite-next-update",text:"Privat die Vorlage für die nächste Nachricht verbessern und im aktuellen Chat nichts mehr schreiben, um nicht weiter zu stören.",feedback:"Eine bessere Vorlage kann künftige Nachrichten erleichtern. Das falsche Datum bleibt aber im Umlauf. Korrigiere die Angabe und behalte eine passende Prüfung vor der nächsten Nachricht bei."}],bestOptionId:"correct-and-check"}},carry:{takeaway:"Bleib fair, kläre deine konkrete Verantwortung und handle entsprechend.",identityExample:"Für deine berichtete Handlung: „Ich habe die Angabe korrigiert“ oder „Ich habe um Unterstützung gebeten.“",followUp:{questionId:"repair-or-support-result",question:"Was hat deine Korrektur oder Unterstützung verändert? Was braucht noch Aufmerksamkeit?",observationPrompt:"Welche Handlung und Antwort hast du festgehalten?",adjustmentPrompt:"Das vorbeugende Startsignal behalten, ändern oder Unterstützung suchen?"}},goDeeper:{sourceIds:["CF08","CF07","CF13"],sections:[{heading:"Freundlichkeit und Verantwortung passen zusammen",paragraphs:["Breines und Chen prüften mitfühlendes Schreiben in vier Experimenten mit Studierenden. Im Experiment zu einem Fehlverhalten wurden 91 Studierende ausgewertet. Sie erinnerten sich an eine Handlung, wegen der sie noch Schuld empfanden, und schrieben sich mit Freundlichkeit und Verständnis. Gemessen wurde mehr Motivation, etwas wiedergutzumachen und das Verhalten nicht zu wiederholen. Das war ein Motivationsmaß. Es beweist weder tatsächliche Wiedergutmachung noch längerfristig größere Verlässlichkeit. [CF08]","ODA ergänzt eine praktische Entscheidung: Kläre deine Verantwortung. Korrigiere dann etwas, biete eine Wiedergutmachung an oder bitte um Unterstützung. Dieser Handlungsschritt und seine zweiminütige Größe waren nicht das geprüfte Vorgehen. Ein harter Satz macht nichts wieder gut. Ein beruhigender Satz allein aber auch nicht. Zeigt deine Notiz, dass jemand dich schlecht behandelt hat, mach dessen Verhalten nicht zu deinem Fehler. Halte den nächsten Schritt sicher und freiwillig. Notiere nur, was du tatsächlich tust. [CF08, CF13]"]},{heading:"Die einzelne Übung ist nicht das geprüfte Programm",paragraphs:["Die Übersicht von Han und Kim umfasst 56 randomisierte Studien zu Selbstmitgefühl. Unmittelbar danach zeigten sich im Durchschnitt kleine bis mittlere Effekte auf Maße psychischer Belastung. Das Verzerrungsrisiko war insgesamt hoch. Weniger Studien verglichen mit anderen aktiven Angeboten oder nutzten Onlineprogramme. Die Übersicht war nicht vorab registriert. Das waren unterschiedliche Programme, kein Test von ODAs einzelnem fairen Satz, sachlicher Korrektur oder gespeichertem Rückblick. Übertrage ihre durchschnittlichen Symptomeffekte nicht als Versprechen auf diese Lektion. [CF07]","Auch nach einer passenden Korrektur kann dir etwas peinlich sein. Vielleicht antwortet niemand oder ein weiterer Schritt wird nötig. Das sind Beobachtungen für den Rückblick. Sie beweisen nicht, dass Freundlichkeit gescheitert ist. Das NIMH empfiehlt professionelle Hilfe, wenn soziale Angst den Alltag stört. Du darfst Unterstützung auch früher suchen. Der Kurs hilft dir, eine Alltagshandlung in seinem Rahmen zu wählen. Anhaltende Angst beurteilt oder behandelt er nicht. [CF13]"]}]}},{schemaVersion:2,revision:2,id:"confidence-5",courseId:"confidence",locale:"de",title:"Wieder am Zögern? Nutze, was schon funktioniert hat",goal:"Nutze deine Notizen. Behalte einen machbaren Sprechversuch und plane die nächste Gelegenheit für diese Woche.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Der Kurs ist zu Ende. Wann bekommt dein Satz diese Woche eine echte Gelegenheit?",reason:{id:"reason-to-continue-speaking",label:"Hilft dir dieser Sprechversuch noch bei dem Leben, das du führen möchtest?",kind:"text",maxLength:160,optional:!0,suggestions:["Mich weiter bei der Arbeit einbringen","Sagen, was ich brauche","Zeit für eine bessere Gelegenheit schützen"]},why:{id:"why-continue-speaking",label:"Was macht es sinnvoll, den Versuch fortzusetzen oder zu ändern?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Nutze Satz und Notizen, statt eine neue Routine anzufangen. Was hast du versucht? Gab es die Gelegenheit? Fehlten Informationen oder musste sich die Situation ändern? Behalte den hilfreichen Teil und ändere eine Bedingung. Fehlt eine Notiz, ist das Ergebnis unbekannt. Das beweist kein Scheitern.","Verknüpfe denselben Satz mit einem verfügbaren Startsignal: „Bei der Übergabe am Samstag stelle ich meine Frage.“ Solche Pläne unterstützten die Zielverfolgung in verschiedenen Studien. Die kombinierte Routine dieses Kurses ist ungeprüft. Wähle diese Woche die nächste passende Gelegenheit und schau danach zurück. Wiederhole, suche Unterstützung, erhole dich oder hör auf, falls der Versuch nicht mehr passt."],example:{title:"Rosa wählt eine andere Gelegenheit",text:"Rosas Notizen zeigen: Zweimal blieb ihre fertige Frage ungestellt, weil die Einweisung für Ehrenamtliche früher endete. Am Samstag fragt sie stattdessen bei einer sicheren Übergabe am Rückgabeschalter. Die Antwort ist knapp. Eine Einzelheit bleibt offen. Rosa hält das Gespräch fest und behält diese Gelegenheit für ihre nächste Schicht. Sie macht den Sprechversuch nicht größer."}},move:{invitation:"Behalte einen hilfreichen Satz. Wähle eine Gelegenheit anhand deiner bisherigen Beobachtungen.",instructions:["Behalte deine gespeicherte Handlung. Nutze eine bewährte Gelegenheit oder ändere eine gescheiterte Bedingung.","Wähle diese Woche einen Termin. Nenne auch Zeit und Ort für deinen Ersatzweg."],prompts:[{id:"retained-speaking-condition",label:"Was behältst du bei? Welche Bedingung muss sich ändern?",help:"Behalte die Handlung. Ändere anhand deiner Notiz das Startsignal oder den Kommunikationsweg.",kind:"text",maxLength:160,optional:!0,visible:!0}],suggestions:{action:["Fragen: Welche Schicht nutzt die kürzere Checkliste?","Meine gespeicherte hilfreiche Bitte wiederholen","Meine gespeicherte überarbeitete Idee teilen"],minimum:["Einen vorbereiteten Satz sagen","Einen hilfreichen Satz senden"],when:[{label:"Heute",daysFromToday:0},{label:"Morgen",daysFromToday:1},{label:"In drei Tagen",daysFromToday:3}],cue:["Bei der Schichtübergabe am Samstag um 10 Uhr","Bei der heutigen Teambesprechung um 15 Uhr"],place:["An unserem Rückgabeschalter","In unserem vertrauten Teamchat"],minutes:[2,1,5],fallback:["Nach der Übergabe der Schichtleitung schreiben","Unterstützung erbitten oder pausieren"],observation:["Startsignal da? Meinen Satz gesagt?","Die Antwort und eine nächste Änderung"]},suggested:{action:"Fragen: Welche Schicht nutzt die kürzere Checkliste?",minimum:"Einen vorbereiteten Satz sagen",minutes:2,cueHint:"Bei der Schichtübergabe am Samstag um 10 Uhr",placeHint:"An unserem Rückgabeschalter",obstacleHint:"Die Schichtübergabe fällt aus.",fallbackHint:"Nach der Übergabe der Schichtleitung schreiben",observationHint:"Startsignal da? Meinen Satz gesagt?"},stopRule:"Behalte Schutzmaßnahmen bei. Pausiere oder hole Unterstützung bei Gefahr, überwältigender Belastung oder Beeinträchtigungen im Alltag.",accessibleAlternative:"Nutze einen sicheren schriftlichen Weg oder Hilfe. Auch Erholung und Unterstützung können deine nächsten gewählten Schritte sein."},result:{question:"Hast du deinen beibehaltenen Satz bei dieser Gelegenheit gesagt?",observationPrompt:"Gab es die Gelegenheit? Was hast du getan? Welche Antwort kam?"},judgment:{primary:{id:"no-question-period-adjustment",scenario:"Rosas Frage ist fertig. Zwei Einweisungen endeten ohne Fragen. Diese Woche kann sie eine sichere Übergabe oder einen vertrauten Nachrichtenkanal nutzen.",question:"Welche Änderung passt zu ihren bisherigen Notizen?",options:[{id:"more-script-practice",text:"Den Plan für die Einweisung beibehalten und die Frage vor dem nächsten geplanten Termin nochmals üben.",feedback:"Üben hilft, wenn Formulierungen oder Wissen fehlen. Rosas Notizen zeigen eine fehlende Gelegenheit. Mehr Textübung ändert diese Bedingung nicht. Wähle stattdessen einen Weg, der verfügbar ist."},{id:"available-route-cue",text:"Dieselbe Frage bei der sicheren Übergabe stellen und den Nachrichtenkanal als Ersatzweg beibehalten.",feedback:"So bleibt die gewählte Handlung erhalten. Geändert wird die Bedingung, die sie verhindert hat. Rosa kann einen Termin wählen, die Antwort notieren und prüfen, ob das neue Startsignal tatsächlich kam."},{id:"longer-team-update",text:"Eine längere Teampräsentation vorbereiten, damit sie nächsten Monat einen eigenen Termin für ihren Beitrag hat.",feedback:"Ein eigener Termin kann später helfen. Er erfordert aber Vorbereitung und verschiebt die fertige Frage, obwohl diese Woche Wege offenstehen. Nutze die Übergabe. Prüfe danach, ob ein größeres Format nötig ist."}],bestOptionId:"available-route-cue"}},carry:{takeaway:"Behalte, was deine Notizen stützen. Gib derselben hilfreichen Handlung die nächste machbare Gelegenheit.",identityExample:"Wenn du den beibehaltenen Satz gesagt hast: „Ich habe meine gewählte Gelegenheit genutzt.“",followUp:{questionId:"retained-opening-result",question:"Hat die neue Gelegenheit das Problem aus deinen früheren Notizen gelöst?",observationPrompt:"Was ergänzt dieser Versuch an deinen bisherigen Beobachtungen?",adjustmentPrompt:"Wiederholen, eine Bedingung ändern, Unterstützung suchen, erholen oder aufhören?"}},goDeeper:{sourceIds:["CF05","CF04","CF13"],sections:[{heading:"Ein Startsignal ist eine erkennbare Situation",paragraphs:["Ein Wenn-dann-Plan verbindet eine wichtige Situation mit einer Handlung, die dem Ziel dient: Wenn die Situation eintritt, tue ich dies. Gollwitzer und Sheeran fassten 94 unabhängige Tests mit 8.461 Teilnehmenden zusammen. Meist waren es Studierende, daneben andere Gruppen. Über die Studien hinweg waren diese Pläne im Durchschnitt vorteilhaft. Aufgaben und Methoden unterschieden sich. Das schätzt weder den Effekt dieses Kurses noch beweist es eine Wirkung des Rückwärtszählens. Startsignal, gewähltes Ziel und machbare Handlung bleiben entscheidend. [CF05]","Entscheide anhand deiner Notizen, welcher Teil sich ändern muss. Gab es keine Gelegenheit, such eine verfügbare. Fehlten Informationen, besorg sie vor dem nächsten Versuch. War Kontakt unsicher, schütze dich und suche Unterstützung. Behalte eine Handlung, die deinem Anliegen weiterhin dient. Mach die Aufgabe nicht größer, nur weil der Kurs endet. Die kombinierte Routine aus Benennen, Verkleinern, Ausprobieren, Festhalten und Rückblick ist eine ODA-Anpassung, kein geprüftes klinisches Programm. [CF04, CF05, CF13]"]},{heading:"Zum Abschluss zählen Beobachtungen, kein Urteil über dein Selbstvertrauen",paragraphs:["Die Übersicht zur Fortschrittskontrolle fand in vielen randomisierten Studien durchschnittliche Vorteile für Ziele. Sie prüfte weder diese konkrete Zusammenfassung noch den Rückblick am nächsten Tag oder den Wochenplan. ODA nutzt sie, um die Zusage und die sachliche Notiz zusammen zurückzubringen. Eine Quizantwort oder ein künftiger Plan belegt kein Sprechen. Ein wirklich gesagter Satz mit unbeantworteter Frage kann eine erledigte Handlung mit offenem äußerem Ergebnis sein. Behalte diese Unterschiede beim nächsten Rückblick. [CF04]","Wähle die nächste Gelegenheit in deiner tatsächlichen Woche. Danach kannst du wiederholen, verkleinern, das Startsignal ändern, Unterstützung suchen, dich erholen, pausieren oder aufhören. Dafür musst du nicht dauerhaft Selbstvertrauen spüren. Die NIMH-Empfehlung verweist bei Beeinträchtigungen im Alltag auf professionelle Beurteilung und Unterstützung, nicht auf den Kursabschluss. Du darfst Hilfe suchen, ohne vorher wiederholt gescheitert zu sein. Setze den Versuch nur fort, solange er sicher, machbar und für dein gewünschtes Leben hilfreich ist. [CF13]"]}]}}];function t(e,s,h){const r=e.judgment.primary.options.find(i=>i.id===e.judgment.primary.bestOptionId),a=e.judgment.primary.options.filter(i=>i!==r).map(i=>i.text);return a.splice(s,0,r.text),{id:e.id,schemaVersion:2,v2:e,title:e.title,goal:e.goal,minutes:e.minutes.learning,reading:[e.idea.paragraphs[0],e.idea.paragraphs.slice(1).join(" ")],practice:[e.move.instructions[0],e.move.instructions.slice(1).join(" ")||"Nutze deine gewählte Handlung bei einer sicheren Gelegenheit.","Kehre hierher zurück und halte fest, was tatsächlich passiert ist."],reflection:e.direction.reason.label,question:e.judgment.primary.question,options:a,correct:s,feedback:r.feedback,takeaway:e.carry.takeaway,sources:[...e.goDeeper.sourceIds],deeper:e.goDeeper.sections,example:e.idea.example,photo:h}}const u={id:"confidence",title:"Deine Stimme zittert. Deine Idee darf trotzdem gehört werden.",subtitle:"Fünf Lektionen. Sag einen sicheren Satz, lerne aus der Antwort und wähle die nächste Gelegenheit.",description:"Führe einen gewählten Sprechversuch weiter: bei einer überschaubaren Gelegenheit, mit ehrlichen Notizen, nötiger Korrektur und einem Plan für nächste Woche.",scope:"Mut und Selbstmitgefühl im Alltag üben. Das ist keine Expositionstherapie für gefährliche Situationen, Trauma oder intensive Angst. Arbeite dabei bitte mit einer ausgebildeten Fachperson.",outcome:"Ein Sprechversuch, eine sachliche Notiz und die nächste Gelegenheit, die zu deiner Woche passt.",photo:{id:"1756244834590-b1a32e94df40",alt:"Frau schaut bei Sonnenaufgang über einen Bergsee"},lang:"de",lessons:[t(n[0],1,{id:"1579017308347-e53e0d2fc5e9",alt:"Person schreibt von Hand in ein offenes Notizbuch"}),t(n[1],2,{id:"1635895752485-99ba511c07e1",alt:"Trittsteine im Wasser bei Sonnenuntergang"}),t(n[2],1,{id:"1572020487535-31e268b25e21",alt:"Mann macht Notizen in einem Notizbuch"}),t(n[3],0,{id:"1573497491208-6b1acb260507",alt:"Zwei Frauen sitzen an einem Tisch und sprechen"}),t(n[4],1,{id:"1748609422318-7301636fb625",alt:"Hand schreibt einen Plan mit Kästchen in ein Notizbuch"})]},c=Object.freeze(Object.defineProperty({__proto__:null,COURSE:u,LESSONS_V2:n,SOURCES:d},Symbol.toStringTag,{value:"Module"}));export{c};
